<?php
/** Same approved composition, populated entirely from WordPress posts. */
defined('ABSPATH') || exit;
$featured=cyberdat_featured_story();
$briefing=cyberdat_briefing_posts( $featured ? $featured->ID : 0 );
$test=cyberdat_editorial_test_environment();
if ( ! $featured && ! $briefing && ! $test ) { return; }
?>
<section class="editorial-lead" aria-labelledby="featured-heading">
 <article class="featured-story" <?php if($featured): ?>data-post-id="<?php echo esc_attr($featured->ID); ?>"<?php endif; ?>>
 <?php if($featured): ?>
  <a class="featured-art" href="<?php echo esc_url(get_permalink($featured)); ?>" tabindex="-1" aria-hidden="true"><?php echo cyberdat_editorial_image($featured->ID,true); // Generated by WordPress or the escaped local fallback. ?></a>
  <div class="featured-body"><div class="story-meta"><span class="section-kicker"><?php esc_html_e('Featured Story','cyberdat'); ?></span><?php if(defined('CYBERDAT_PLAYGROUND') && CYBERDAT_PLAYGROUND): ?><span class="sample-label">SAMPLE DATA</span><?php endif; ?></div><h2 id="featured-heading"><a href="<?php echo esc_url(get_permalink($featured)); ?>"><?php echo esc_html(get_the_title($featured)); ?></a></h2><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags(strip_shortcodes(get_the_excerpt($featured))),34)); ?></p><div class="article-meta"><span><?php echo esc_html(cyberdat_editorial_category($featured->ID)); ?></span><span aria-hidden="true">/</span><time datetime="<?php echo esc_attr(get_the_date(DATE_W3C,$featured)); ?>"><?php echo esc_html(get_the_date('M j, Y',$featured)); ?></time><span aria-hidden="true">/</span><span><?php echo esc_html(cyberdat_editorial_format($featured->ID)); ?></span></div></div>
 <?php elseif($test): ?>
  <div class="featured-body"><h2 id="featured-heading"><?php esc_html_e('No published stories yet','cyberdat'); ?></h2><p><?php esc_html_e('Publish a test post and select it as Featured Story to preview this block.','cyberdat'); ?></p></div>
 <?php endif; ?>
 </article>
 <aside class="news-rail" aria-labelledby="news-heading"><div class="section-topline"><h2 id="news-heading"><?php esc_html_e('The Briefing','cyberdat'); ?></h2><span class="rail-label"><?php echo esc_html(defined('CYBERDAT_PLAYGROUND') && CYBERDAT_PLAYGROUND ? __('LATEST / SAMPLE','cyberdat') : __('LATEST NEWS','cyberdat')); ?></span></div>
 <?php foreach($briefing as $item): ?>
  <article class="brief-item" data-post-id="<?php echo esc_attr($item->ID); ?>"><div><div class="story-meta"><span><?php echo esc_html(cyberdat_editorial_category($item->ID)); ?></span></div><h3><a href="<?php echo esc_url(get_permalink($item)); ?>"><?php echo esc_html(get_the_title($item)); ?></a></h3><div class="brief-date"><?php if(defined('CYBERDAT_PLAYGROUND') && CYBERDAT_PLAYGROUND): ?><span class="sample-label">SAMPLE</span><?php endif; ?><time datetime="<?php echo esc_attr(get_the_date(DATE_W3C,$item)); ?>"><?php echo esc_html(get_the_date('M j',$item)); ?></time></div></div><a class="brief-thumbnail" href="<?php echo esc_url(get_permalink($item)); ?>" tabindex="-1" aria-hidden="true"><?php echo cyberdat_editorial_image($item->ID); ?></a></article>
 <?php endforeach; ?>
 <?php if(!$briefing && $test): ?><p class="brief-date"><?php esc_html_e('No published News stories yet.','cyberdat'); ?></p><?php endif; ?>
 <a class="text-link rail-bottom" href="<?php echo esc_url(home_url('/news/')); ?>"><?php esc_html_e('All news','cyberdat'); ?> <span aria-hidden="true">↗</span></a></aside>
</section>
